{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let cands = null
let ballots = []
let seenBallot = false
const NAME = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  if (w[0] === 'candidates') {
    if (cands !== null || seenBallot) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (w.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const set = new Set()
    for (const name of w.slice(1)) {
      if (!NAME.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (set.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      set.add(name)
    }
    cands = [...set]
  } else if (w[0] === 'ballot') {
    if (w.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(w[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of w.slice(2)) {
      if (cands === null || !cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    seenBallot = true
    ballots.push({ count: BigInt(w[1]), prefs: w.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const total = ballots.reduce((a, b) => a + b.count, 0n)
const alive = new Set(cands)
const history = new Map(cands.map((c) => [c, []]))
const out = []
let roundNo = 0
let winner = null
for (;;) {
  roundNo++
  const counts = new Map([...alive].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => alive.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const list = [...counts.entries()].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : 1))
  let line = `round ${roundNo}: ` + list.map(([c, v]) => `${c}=${v}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0n) break
  const top = list.find(([, v]) => v * 2n > active)
  if (top) {
    winner = top[0]
    break
  }
  let tied
  const min = list.reduce((m, [, v]) => (v < m ? v : m), list[0][1])
  tied = list.filter(([, v]) => v === min).map(([c]) => c)
  for (let r = 0; r < roundNo && tied.length > 1; r++) {
    const m = tied.reduce((x, c) => (history.get(c)[r] < x ? history.get(c)[r] : x), history.get(tied[0])[r])
    const next = tied.filter((c) => history.get(c)[r] === m)
    if (next.length < tied.length) {
      tied = next
      r = -1
    }
  }
  const elim = tied.reduce((a, b) => (b > a ? b : a))
  alive.delete(elim)
  out.push(`eliminated ${elim}`)
}
const end = winner ? `winner ${winner}` : 'no winner'
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + end + '\n')
else process.stdout.write(`rounds ${roundNo}\n${end}\n`)
EOF
